47	
48	    // Numeric text is sent as a number; anything else is sent as text so the API can reject it.
49	    // An empty field is omitted so the API default applies.
50	    function fieldValue(text) {
51	      const trimmed = text.trim();
52	      if (trimmed === '') return undefined;
53	      const n = Number(trimmed);
54	      return Number.isFinite(n) ? n : text;
55	    }
56	
57	    function describeRejection(status, data) {
58	      const error = data && data.error;
59	      if (!error) return `Request failed (HTTP ${status}).`;
60	      let message = error.message || `Request failed (HTTP ${status}).`;
61	      if (Array.isArray(error.fields) && error.fields.length > 0) {
62	        message += ' ' + error.fields.map((f) => `${f.field}: ${f.message}`).join(' ');
63	      }
64	      return message;
65	    }
