107	      }
108	    }
109	
110	    form.addEventListener('submit', async (event) => {
111	      event.preventDefault();
112	      formError.textContent = '';
113	
114	      const body = { input: inputField.value };
115	      const steps = fieldValue(stepsField.value);
116	      const failAttempts = fieldValue(failAttemptsField.value);
117	      if (steps !== undefined) body.steps = steps;
118	      if (failAttempts !== undefined) body.failAttempts = failAttempts;
119	
